-- 与 v5notes 对齐：文件预览开关使用 sys.file.previewListResource
UPDATE sys_config
SET config_name = '文件预览列表资源开关', config_key = 'sys.file.previewListResource'
WHERE config_key = 'sys.oss.previewListResource';

